window.RP_SESSION={"id":"S-a95bea328048","messages":[{"id":"RP-III-0004655","time":"2026-01-08T19:03:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 원래 머리 식히는 데에는..~ 맥주.\"\n\n오늘의 글공부를 알차게 끝낸 그녀는 길드의 홀로 나와 오늘은 조금, 그래, 반컵만을 채워 한 모금 들이켰습니다.\n\n\"하아..! 살 것같... 다..\"\n\n맥주를 마셔서인가, 공부를 해서인가 머리를 쥐어짜는 듯한 두통이 밀려왔습니다. 어느새 어느 정도 익숙해진 그 통증이 느껴졌습니다.\n\n\u003c오오, 나만의 이리도 사랑스럽고 아리따운 피조물아... 내가 너를 위해 어찌나 갖은 노력을 하였는데, 그리 연인에게 푹~ 빠져 날 위해 기도하지 않는 게냐?>\n\n머릿속에 늘 들리던 목소리는 서글픈 듯 말했습니다.\n\n\u003c아아 나의 마리아, 내 작은 딸... 이 아비의 목소리를 들으렴. 떠올려보렴 이 아비가 네게 거짓말했던 적이라도 있더냐? 난 그리도 너를 신임하여 신성력까지 쥐여주어 널 태어나게 했는데... 넌 어찌하여 불효를 저지르느냐?>\n\n그녀는 남은 맥주를 진창 들이켰습니다. 저번에 아카쿠씨의 조언을 들을 이유로 마음이 심란했기에 오늘... 지금만큼은","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0004656","time":"2026-01-08T19:03:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0004657","time":"2026-01-08T19:03:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
